export type Snapshot_Serialize = {
	jobs: Job_Serialize[],
	preview: Preview_Serialize | null,
	settings: Settings_Serialize,
	components: Components,
	system: SystemInfo,
};

export type Source = "paste" | "typed" | "drop" | "deepLink" | "clipboard" | "playlist" | "again";

export type SponsorBlock = "off" | "remove" | "mark";

/**  What the job is doing right now. The UI turns this into words. */
export type Stage = "waiting" | "probing" | "preparing" | "video" | "audio" | "media" | "subtitles" | "merging" | "extractingAudio" | "converting" | "embeddingMetadata" | "embeddingThumbnail" | "embeddingSubtitles" | "sponsorBlock" | "fixing" | "moving" | "waitingForLive" | "done";

/**  System facts the UI styles itself with. Filled in by the shell, not the engine. */
export type SystemInfo = {
	/**  The user's accent color as `#rrggbb`, or empty to use the fallback. */
	accent: string,
	/**  Whether a real system material is behind the window. */
	material: boolean,
	appVersion: string,
};

export type Tool = {
	id: ToolId,
	status: ToolStatus,
	version: string,
	/**  Newer version available for a managed tool, if a check found one. */
	latest: string,
	path: string,
	origin: ToolOrigin,
};

export type ToolId = "ytdlp" | "ffmpeg" | "deno";

export type ToolOrigin = 
/**  Installed and updated by lovelyDL. */
"managed" | 
/**  Found on PATH. */
"system" | 
/**  A path the user set. */
"custom";

export type ToolStatus = { status: "missing" } | { status: "checking" } | 
/**  Downloading or unpacking; `fraction` runs from 0 to 1. */
{ status: "installing"; fraction: number | null } | { status: "ready" } | { status: "broken"; message: string };

/**  A request from outside the web view (tray, deep link, second launch) that the UI acts on. */
export type UiCommand = "newDownload" | "showDownloads" | "showFailed" | "confirmQuit" | "checkClipboard";

export type Update = Update_Serialize | Update_Deserialize;

export type Update_Deserialize = Change_Deserialize[];

export type Update_Serialize = Change_Serialize[];

export type WindowAction = "close" | "minimize" | "zoom" | 
/**  Shows the window once the UI has painted, so there is never a blank frame. */
"show";

/* Tauri Specta runtime */
type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

type EventEmitTo<T> = [T] extends [null] ? (target: __TAURI_EVENT.EventTarget | string) => Promise<void> : (target: __TAURI_EVENT.EventTarget | string, payload: T) => Promise<void>;

function makeEvent<TListen, TEmit = TListen>(name: string, serialize?: (payload: TEmit) => unknown, deserialize?: (payload: any) => TListen) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<TListen>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: TEmit) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => __TAURI_EVENT.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => target.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
    });

    return Object.assign(fn, base);
}

/* Tauri Specta mocks */

/** A handler for each generated command, keyed by its `commands` accessor. */
export type MockCommandHandlers = {
    getSnapshot: () => Snapshot_Serialize | Promise<Snapshot_Serialize>,
    addLinks: (args: { text: string; source: Source }) => number | Promise<number>,
    previewUpdate: (args: { id: string; request: DownloadRequest_Deserialize }) => void | Promise<void>,
    previewChoose: (args: { id: string; choice: PlaylistChoice }) => void | Promise<void>,
    previewDismiss: (args: { id: string }) => void | Promise<void>,
    previewStart: (args: { id: string; request: DownloadRequest_Deserialize; selection: string[]; skipDownloaded: boolean }) => null | Promise<null>,
    jobPause: (args: { id: string }) => void | Promise<void>,
    jobResume: (args: { id: string }) => void | Promise<void>,
    jobCancel: (args: { id: string }) => void | Promise<void>,
    jobRetry: (args: { id: string }) => void | Promise<void>,
    jobRemove: (args: { ids: string[] }) => void | Promise<void>,
    jobApplyFix: (args: { id: string; fix: Fix }) => void | Promise<void>,
    jobUpdateRequest: (args: { id: string; request: DownloadRequest_Deserialize }) => null | Promise<null>,
    jobFormats: (args: { id: string }) => MediaInfo_Serialize | Promise<MediaInfo_Serialize>,
    jobsReorder: (args: { ids: string[] }) => void | Promise<void>,
    pauseAll: () => void | Promise<void>,
    resumeAll: () => void | Promise<void>,
    retryFailed: () => void | Promise<void>,
    clearCompleted: () => void | Promise<void>,
    historyQuery: (args: { query: string; filter: HistoryFilter; offset: number; limit: number }) => HistoryPage_Serialize | Promise<HistoryPage_Serialize>,
    historyRemove: (args: { ids: string[] }) => void | Promise<void>,
    historyTrash: (args: { ids: string[] }) => null | Promise<null>,
    downloadAgain: (args: { id: string }) => null | Promise<null>,
    reveal: (args: { id: string }) => null | Promise<null>,
    openFile: (args: { id: string }) => null | Promise<null>,
    openFolder: () => null | Promise<null>,
    copyLink: (args: { id: string }) => null | Promise<null>,
    copyText: (args: { text: string }) => null | Promise<null>,
    jobDetails: (args: { id: string }) => string | Promise<string>,
    settingsSet: (args: { settings: Settings_Deserialize }) => null | Promise<null>,
    chooseFolder: (args: { start: string }) => string | null | Promise<string | null>,
    checkFolder: (args: { path: string }) => null | Promise<null>,
    templatePreview: (args: { template: string }) => string | Promise<string>,
    componentsRefresh: () => void | Promise<void>,
    componentInstall: (args: { tool: ToolId }) => null | Promise<null>,
    componentsInstallMissing: () => null | Promise<null>,
    componentRollback: (args: { tool: ToolId }) => null | Promise<null>,
    clipboardTakeLink: () => number | Promise<number>,
    clipboardDismiss: () => void | Promise<void>,
    windowAction: (args: { action: WindowAction }) => null | Promise<null>,
    windowLabel: () => string | Promise<string>,
    quit: () => null | Promise<null>,
    openSettings: () => null | Promise<null>,
    openLink: (args: { link: Link }) => null | Promise<null>,
    appUpdateCheck: () => string | null | Promise<string | null>,
    appUpdateInstall: () => null | Promise<null>,
};

/**
 * Install typed mock handlers for the generated commands.
 *
 * Handlers are installed through `@tauri-apps/api/mocks`'s `mockIPC`, so the application
 * under test keeps importing the real `commands` object and still runs the argument and
 * result transforms around each call.
 *
 * A handler receives the command's arguments and returns its success value; throw (or
 * return a rejected promise) to make the command fail. A command with no handler rejects
 * with an error rather than resolving `undefined`, so a test can't pass by accident.
 *
 * Tauri's event mocking is enabled as part of the install (`shouldMockEvents`), so
 * `events` keeps working under test without a second installer fighting this one. Note
 * that Tauri's own mock does not implement `emitTo`, which resolves without reaching any
 * listener. Call `clearMocks` from `@tauri-apps/api/mocks` between tests.
 */
export function mockCommands(handlers: Partial<MockCommandHandlers> = {}): void {
    // A copy with no prototype, so a command named after an `Object.prototype` member
    // (`toString`, `constructor`, …) reports that it is unregistered instead of calling
    // whatever the prototype happens to provide.
    const mockHandlers: Partial<MockCommandHandlers> = Object.create(null);
    Object.assign(mockHandlers, handlers);
    return __TAURI_MOCK_IPC((cmd, args) => {
        switch (cmd) {
            case "get_snapshot": return mockCommandHandler(mockHandlers.getSnapshot, "get_snapshot", args);
            case "add_links": return mockCommandHandler(mockHandlers.addLinks, "add_links", args);
            case "preview_update": return mockCommandHandler(mockHandlers.previewUpdate, "preview_update", args);
            case "preview_choose": return mockCommandHandler(mockHandlers.previewChoose, "preview_choose", args);
            case "preview_dismiss": return mockCommandHandler(mockHandlers.previewDismiss, "preview_dismiss", args);
            case "preview_start": return mockCommandHandler(mockHandlers.previewStart, "preview_start", args);
            case "job_pause": return mockCommandHandler(mockHandlers.jobPause, "job_pause", args);
            case "job_resume": return mockCommandHandler(mockHandlers.jobResume, "job_resume", args);
            case "job_cancel": return mockCommandHandler(mockHandlers.jobCancel, "job_cancel", args);
            case "job_retry": return mockCommandHandler(mockHandlers.jobRetry, "job_retry", args);
            case "job_remove": return mockCommandHandler(mockHandlers.jobRemove, "job_remove", args);
            case "job_apply_fix": return mockCommandHandler(mockHandlers.jobApplyFix, "job_apply_fix", args);
            case "job_update_request": return mockCommandHandler(mockHandlers.jobUpdateRequest, "job_update_request", args);
            case "job_formats": return mockCommandHandler(mockHandlers.jobFormats, "job_formats", args);
            case "jobs_reorder": return mockCommandHandler(mockHandlers.jobsReorder, "jobs_reorder", args);
            case "pause_all": return mockCommandHandler(mockHandlers.pauseAll, "pause_all", args);
            case "resume_all": return mockCommandHandler(mockHandlers.resumeAll, "resume_all", args);
            case "retry_failed": return mockCommandHandler(mockHandlers.retryFailed, "retry_failed", args);
            case "clear_completed": return mockCommandHandler(mockHandlers.clearCompleted, "clear_completed", args);
            case "history_query": return mockCommandHandler(mockHandlers.historyQuery, "history_query", args);
            case "history_remove": return mockCommandHandler(mockHandlers.historyRemove, "history_remove", args);
            case "history_trash": return mockCommandHandler(mockHandlers.historyTrash, "history_trash", args);
            case "download_again": return mockCommandHandler(mockHandlers.downloadAgain, "download_again", args);
            case "reveal": return mockCommandHandler(mockHandlers.reveal, "reveal", args);
            case "open_file": return mockCommandHandler(mockHandlers.openFile, "open_file", args);
            case "open_folder": return mockCommandHandler(mockHandlers.openFolder, "open_folder", args);
            case "copy_link": return mockCommandHandler(mockHandlers.copyLink, "copy_link", args);
            case "copy_text": return mockCommandHandler(mockHandlers.copyText, "copy_text", args);
            case "job_details": return mockCommandHandler(mockHandlers.jobDetails, "job_details", args);
            case "settings_set": return mockCommandHandler(mockHandlers.settingsSet, "settings_set", args);
            case "choose_folder": return mockCommandHandler(mockHandlers.chooseFolder, "choose_folder", args);
            case "check_folder": return mockCommandHandler(mockHandlers.checkFolder, "check_folder", args);
            case "template_preview": return mockCommandHandler(mockHandlers.templatePreview, "template_preview", args);
            case "components_refresh": return mockCommandHandler(mockHandlers.componentsRefresh, "components_refresh", args);
            case "component_install": return mockCommandHandler(mockHandlers.componentInstall, "component_install", args);
            case "components_install_missing": return mockCommandHandler(mockHandlers.componentsInstallMissing, "components_install_missing", args);
            case "component_rollback": return mockCommandHandler(mockHandlers.componentRollback, "component_rollback", args);
            case "clipboard_take_link": return mockCommandHandler(mockHandlers.clipboardTakeLink, "clipboard_take_link", args);
            case "clipboard_dismiss": return mockCommandHandler(mockHandlers.clipboardDismiss, "clipboard_dismiss", args);
            case "window_action": return mockCommandHandler(mockHandlers.windowAction, "window_action", args);
            case "window_label": return mockCommandHandler(mockHandlers.windowLabel, "window_label", args);
            case "quit": return mockCommandHandler(mockHandlers.quit, "quit", args);
            case "open_settings": return mockCommandHandler(mockHandlers.openSettings, "open_settings", args);
            case "open_link": return mockCommandHandler(mockHandlers.openLink, "open_link", args);
            case "app_update_check": return mockCommandHandler(mockHandlers.appUpdateCheck, "app_update_check", args);
            case "app_update_install": return mockCommandHandler(mockHandlers.appUpdateInstall, "app_update_install", args);
            default: throw new Error(`No mock handler registered for command '${cmd}'`);
        }
    }, { shouldMockEvents: true });
}

function mockCommandHandler(handler: ((args: any) => unknown) | undefined, name: string, args: unknown): unknown {
    if (handler === undefined) throw new Error(`No mock handler registered for command '${name}'`);
    return handler(args);
}
